const allowed = ['schemaVersion','eventId','eventType','occurredAt','clusterId','clusterName','sourceType','environment','severity','title','summary','resourceId','resourceKind','resourceName','namespace','region','service','accountId','action','resourceState'];
const items = $input.all();
const getHeader = (headers, name) => {
  const key = Object.keys(headers || {}).find((candidate) => candidate.toLowerCase() === name.toLowerCase());
  return key ? headers[key] : undefined;
};
const parseObject = (value, label) => {
  if (typeof value === 'string') {
    try { value = JSON.parse(value); }
    catch { throw new Error(`Invalid ${label}: expected a JSON object`); }
  }
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
};
return items.flatMap((item, index) => {
  const root = parseObject(item.json, 'webhook input');
  const headers = parseObject(root.headers, 'webhook headers');
  let body = root.body !== undefined ? parseObject(root.body, 'request body') : root;
const isEventBridge = Boolean(body && body.id && body.source && body["detail-type"]);
if (isEventBridge) {
  const envelope = body;
  const detail = parseObject(envelope.detail, "EventBridge detail");
  const alarmName = String(detail.alarmName || "");
  const state = detail.state && typeof detail.state === "object" ? detail.state.value : detail.state;
  const eventType = String(envelope["detail-type"] || "AWS EventBridge Event");
  let severity = "info";
  if (eventType.toLowerCase().includes("cloudwatch alarm") && state === "ALARM") {
    severity = /statuscheckfailed|errors|dead.?letter|dlq/i.test(alarmName) ? "critical" : "high";
  } else if (eventType.toLowerCase().includes("instance state-change")) {
    severity = detail.state === "terminated" ? "critical" : ["stopped", "stopping", "shutting-down"].includes(detail.state) ? "medium" : "low";
  } else if (envelope.source === "aws.guardduty") {
    const score = Number(detail.severity || 0);
    severity = score >= 7 ? "critical" : score >= 4 ? "high" : "medium";
  } else if (envelope.source === "aws.securityhub") {
    const label = String(detail.findings?.[0]?.Severity?.Label || "").toLowerCase();
    severity = label === "critical" ? "critical" : label === "high" ? "high" : label === "medium" ? "medium" : "low";
  }
  const finding = detail.findings?.[0] || {};
  body = {
    ...detail,
    eventId: envelope.id,
    eventType,
    occurredAt: envelope.time,
    sourceType: envelope.source,
    region: envelope.region,
    accountId: envelope.account,
    resourceId: detail["instance-id"] || alarmName || detail.functionName || detail.resource?.resourceId || finding.Resources?.[0]?.Id || "",
    resourceState: state || "",
    service: envelope.source === "aws.guardduty" ? "AWS/GuardDuty" : envelope.source === "aws.securityhub" ? "AWS/SecurityHub" : alarmName.toLowerCase().includes("lambda") ? "AWS/Lambda" : alarmName.toLowerCase().includes("server") ? "AWS/EC2" : "AWS",
    severity,
    title: alarmName || detail["instance-id"] || finding.Title || detail.title || eventType,
    summary: detail.state && typeof detail.state === "object" ? (detail.state.reason || detail.state.value || "CloudWatch alarm state changed") : (finding.Description || detail.description || detail.message || detail.reason || String(state || "AWS event received"))
  };
}

  // Accept common event wrappers used by API gateways and event relays.
  for (const key of ['data', 'detail', 'payload']) {
    if ((!body.eventId || !body.eventType) && body[key] !== undefined) {
      const nested = parseObject(body[key], key);
      if (Object.keys(nested).length) body = nested;
    }
  }
  const headerEventId = getHeader(headers, 'x-cs-event-id');
  const eventId = String(body.eventId || headerEventId || '').trim();
  const eventType = String(body.eventType || '').trim();
  if (!eventId && !eventType && Object.keys(body).length === 0) {
    // n8n editor can execute this node without webhook input. Treat that as a no-op,
    // not a failed workflow; a real event must include both required identifiers.
    return [];
  }
  if (!eventId || !eventType) {
    const keys = Object.keys(body).slice(0, 20).join(', ') || '(none)';
    throw new Error(`Invalid CloudSentinels event at item ${index + 1}: eventId and eventType are required. Received keys: ${keys}. Send a JSON object with both fields.`);
  }
  if (eventId.length > 128 || eventType.length > 80) throw new Error('Rejected event: eventId or eventType exceeds the allowed length');
  const event = {};
  for (const key of allowed) if (body[key] !== undefined) event[key] = body[key];
  event.eventId = eventId;
  event.eventType = eventType;
  event.severity = String(event.severity || 'info').toLowerCase();
  const validSeverities = ['critical','high','degraded','warning','medium','low','info'];
  if (!validSeverities.includes(event.severity)) event.severity = 'info';
  const type = eventType.toLowerCase();
  let route = 'general';
  if (type.includes('recover') || type.includes('online') || type.includes('healthy')) route = 'recovery';
  else if (event.severity === 'critical' || type.includes('offline') || type.includes('notready')) route = 'critical';
  else if (['high','degraded','warning','medium'].includes(event.severity) || type.includes('degraded') || type.includes('warning') || type.includes('crashloop')) route = 'degraded';
  const safe = (value, max) => String(value || '').replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, max);
  return { json: { ...event, title: safe(event.title || eventType, 180), summary: safe(event.summary, 1000), clusterName: safe(event.clusterName, 120), route, receivedAt: new Date().toISOString(), receiver: 'n8n-local', signaturePresent: Boolean(getHeader(headers, 'x-cs-signature') && getHeader(headers, 'x-cs-timestamp')), autoRemediation: false } };
});

const e = $input.first().json;
const type = String(e.eventType || "").toLowerCase();
const source = String(e.sourceType || "").toLowerCase();
const text = [type, source, e.title, e.summary, e.service, e.resourceId, e.resourceState].join(" ").toLowerCase();

let target = "cloudsentinels-core";
let adapter = "core-incident-policy";
let actions = [];
let mutationActions = [];
let status = "observe-and-audit";
let reason = "Event is recorded and triaged; no target-specific mutation adapter is selected.";

if (/lambda|serverless/.test(text)) {
  target = "aws-lambda";
  adapter = "aws-lambda-readonly";
  actions = ["inspect-errors", "inspect-throttles", "inspect-duration", "inspect-logs", "check-concurrency"];
  status = "manual-review";
  reason = "Lambda diagnostics are supported by monitoring; version-alias rollback or configuration changes are not enabled in this workflow.";
} else if (/ec2|aws-server|instance-state|status-check|cpu-high/.test(text)) {
  target = "aws-ec2";
  adapter = "aws-ec2-readonly";
  actions = ["inspect-instance-state", "inspect-status-checks", "inspect-cpu-metrics", "inspect-system-logs"];
  status = "manual-review";
  reason = "EC2 monitoring is read-only. SSM access and an approved instance remediation adapter are not yet configured.";
} else if (/n8n-delivery|dlq|dead.?letter|eventbridge/.test(text)) {
  target = "aws-event-pipeline";
  adapter = "aws-sqs-readonly";
  actions = ["inspect-eventbridge-rules", "inspect-sqs-queue-age", "inspect-delivery-dlq"];
  status = "manual-review";
  reason = "AWS event delivery diagnostics are available; queue purging, target rewiring and retry-policy changes require separate operator approval.";
} else if (/kubernetes|k8s|podcrashloop|deploymentunhealthy|nodenotready|memorypressure|cputhreshold/.test(text)) {
  target = "kubernetes";
  adapter = "cloudsentinels-agent";
  actions = ["collect-snapshot"];
  status = "diagnostic-ready";
  reason = "The authenticated local agent can collect a cluster snapshot. Mutating commands remain allowlisted and approval-gated.";
  if (type.includes("deploymentunhealthy") && e.namespace && e.resourceName) {
    actions.push("rollout-status");
    mutationActions = ["restart-deployment", "rollback-deployment"];
    actions.push(...mutationActions);
    status = "approval-required";
    reason = "A specific deployment was identified. Restart or rollback can only be queued after signed human approval and is limited by the agent action and namespace allowlists.";
  } else if (type.includes("podcrashloop")) {
    actions.push("rollout-status");
    reason = "Capture diagnostics and identify the owning deployment before any restart; the event identifies a pod, not a safe deployment target.";
  } else if (type.includes("nodenotready") || type.includes("memorypressure")) {
    reason = "Capture diagnostics and escalate. Node drain, eviction, and destructive node operations are not in the agent allowlist.";
  }
} else if (/guardduty|securityhub|threat|security|unauthorized|credential|intrusion|malware/.test(text)) {
  target = "security-event";
  adapter = "security-evidence-review";
  actions = ["preserve-event-evidence", "review-cloudtrail-and-guardduty", "human-containment-review"];
  status = "security-review-required";
  reason = "Security events are escalated for human investigation; automatic isolation or credential changes are deliberately disabled.";
}

const lifecycle = [
  "ingest-and-authenticate",
  "normalize-and-validate",
  "correlate-and-deduplicate-by-event-id",
  "classify-severity-and-target",
  "collect-read-only-diagnostics",
  "evaluate-target-specific-allowlist",
  "require-signed-human-approval-for-mutations",
  "execute-only-through-authorized-target-adapter",
  "verify-health-and-rollout",
  "rollback-or-escalate-on-verification-failure",
  "write-audit-and-recovery-event"
];

return [{json:{
  ...e,
  target,
  remediation: {
    target,
    adapter,
    status,
    reason,
    recommendedActions: actions,
    mutationActions,
    requiresHumanApproval: mutationActions.length > 0 || status === "manual-review" || status === "security-review-required",
    canExecuteFromN8n: false,
    remediationExecuted: false,
    idempotencyKey: e.eventId
  },
  sharedLifecycle: lifecycle,
  remediationExecuted: false
}}];
